import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int n = Integer.parseInt(br.readLine().trim()); int[] a = new int[n]; StringTokenizer st = new StringTokenizer(br.readLine()); for (int i = 0; i < n; i++) { a[i] = Integer.parseInt(st.nextToken()); } Map<Integer, Integer> counts = new HashMap<>(); for (int i = 0; i < n; i++) { int min = a[i]; for (int j = i; j < n; j++) { min = Math.min(min, a[j]); counts.put(min, counts.getOrDefault(min, 0) + 1); } } int q = Integer.parseInt(br.readLine().trim()); PrintWriter out = new PrintWriter(System.out); while (q-- > 0) { int k = Integer.parseInt(br.readLine().trim()); out.println(counts.getOrDefault(k, 0)); } out.flush(); out.close(); } }